algorithms.pseudocode:
function CLASSIFY(j, m):
    naive   <- (2*j < m)                  # tier 1: O(1)
    exact   <- (3^j < 2^m)                # tier 3: exact big integers (ground truth)
    sharp_fp<- (j*log 3 < m*log 2)        # tier 2: O(1) floating point
    if sharp_fp != exact:                 # at the fp boundary, trust exact
        sharp <- exact
    else:
        sharp <- sharp_fp
    ratio   <- (j / m) if m > 0 else +inf
    reclaimed <- sharp AND (NOT naive)
    return { contracts: exact, naive_cert: naive,
             sharp_cert: sharp, reclaimed: reclaimed, ratio: ratio }
